CREATE TABLE IF NOT EXISTS `User` (`userID` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `username` TEXT, `password` TEXT)
CREATE TABLE IF NOT EXISTS `Profile` (`profileID` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `firstName` TEXT, `lastName` TEXT, `observationDate` TEXT, `leaArrestDate` TEXT, `commitmentDate` TEXT, `notCommittedToJail` INTEGER NOT NULL, `disqualifiedForCPI` INTEGER NOT NULL, `disqualifiedForTimeAllowances` INTEGER NOT NULL, `stalPercent` INTEGER NOT NULL, `deductionDays` INTEGER NOT NULL, `timeGapDays` INTEGER NOT NULL, `userID` INTEGER NOT NULL, `image_path` TEXT, `convictionDate` TEXT, `sentenceServiceStartDate` TEXT, `imprisonmentStartDate` TEXT, `jailCommitmentDate` TEXT, `prisonCommitmentDate` TEXT, `cpiCreditPercent` INTEGER NOT NULL DEFAULT 0, `custodyTimelineConfirmed` INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(`userID`) REFERENCES `User`(`userID`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_Profile_userID` ON `Profile` (`userID`)
CREATE TABLE IF NOT EXISTS `ProfileCharge` (`profileID` INTEGER NOT NULL, `position` INTEGER NOT NULL, `minYears` INTEGER NOT NULL, `minMonths` INTEGER NOT NULL, `minDays` INTEGER NOT NULL, `maxYears` INTEGER NOT NULL, `maxMonths` INTEGER NOT NULL, `maxDays` INTEGER NOT NULL, PRIMARY KEY(`profileID`, `position`), FOREIGN KEY(`profileID`) REFERENCES `Profile`(`profileID`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_ProfileCharge_profileID` ON `ProfileCharge` (`profileID`)
